/* ══════════════════════════════════════
   LESSON SCREEN STYLES
══════════════════════════════════════ */

/* Lesson Mode Navigation */
.lesson-mode-nav {
  display: flex;
  gap: 8px;
  padding: 16px;
  background: var\(--bg-white\);
  border-bottom: 1px solid var\(--border\);
  position: sticky;
  top: 0;
  z-index: 10;
}

.lesson-mode-btn {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 12px 16px;
  border: 1px solid var\(--border\);
  border-radius: 12px;
  background: var\(--bg-white\);
  color: var\(--text-med\);
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
}

.lesson-mode-btn i {
  width: 16px;
  height: 16px;
}

.lesson-mode-btn.active {
  background: var\(--blue\);
  color: white;
  border-color: var\(--blue\);
  box-shadow: 0 2px 8px rgba\(59, 130, 246, 0.2\);
}

.lesson-mode-btn:hover:not\(.active\) {
  background: var\(--bg-blue\);
  border-color: var\(--blue-subtle\);
}

/* Progress Bar */
.lesson-progress-bar {
  width: 100%;
  height: 4px;
  background: var\(--border\);
  border-radius: 2px;
  overflow: hidden;
  margin: 20px 0 8px 0;
}

.lesson-progress-fill {
  height: 100%;
  background: linear-gradient\(90deg, var\(--blue\), var\(--green\)\);
  transition: width 0.3s ease;
}

.lesson-progress-text {
  text-align: center;
  font-size: 13px;
  color: var\(--text-med\);
  margin-bottom: 24px;
  font-weight: 500;
}

/* Flashcard Container */
.flashcard-container {
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 32px 20px;
  min-height: 350px;
}

.flashcard {
  width: 100%;
  max-width: 400px;
  min-height: 280px;
  background: white;
  border-radius: 20px;
  box-shadow: 0 8px 32px var\(--shadow\), 0 2px 8px rgba\(0,0,0,0.06\);
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 32px;
  border: 1px solid var\(--border\);
}

.flashcard:hover {
  transform: translateY\(-4px\);
  box-shadow: 0 12px 40px rgba\(0,0,0,0.12\);
}

.flashcard-front,
.flashcard-back {
  text-align: center;
  width: 100%;
}

.flashcard-hanzi {
  font-family: "Noto Serif SC", serif;
  font-size: 64px;
  font-weight: 400;
  color: var\(--text-dark\);
  margin-bottom: 16px;
  line-height: 1.2;
}

.flashcard-pinyin {
  font-size: 24px;
  color: var\(--text-med\);
  margin-bottom: 20px;
  font-weight: 400;
}

.flashcard-hint {
  font-size: 13px;
  color: var\(--text-light\);
  margin-top: 20px;
  font-style: italic;
}

.flashcard-en {
  font-size: 28px;
  font-weight: 600;
  color: var\(--blue\);
  margin-bottom: 16px;
}

.flashcard-defs {
  margin-top: 16px;
  text-align: left;
}

.flashcard-def {
  font-size: 14px;
  color: var\(--text-med\);
  line-height: 1.6;
  margin-bottom: 6px;
}

.flashcard-pos {
  margin-top: 16px;
  font-size: 12px;
  color: var\(--text-light\);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-weight: 600;
}

/* Audio Controls */
.lesson-audio-controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  padding: 0 20px 24px 20px;
}

.lesson-btn-audio {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 24px;
  border: 1px solid var\(--blue\);
  border-radius: 12px;
  background: var\(--blue\);
  color: white;
  font-size: 15px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
}

.lesson-btn-audio:hover {
  background: #2563eb;
  transform: translateY\(-1px\);
  box-shadow: 0 4px 12px rgba\(59, 130, 246, 0.3\);
}

.lesson-btn-audio.secondary {
  background: white;
  color: var\(--blue\);
}

.lesson-btn-audio.secondary:hover {
  background: var\(--bg-blue\);
}

.lesson-btn-audio i {
  width: 18px;
  height: 18px;
}

/* Navigation Buttons */
.lesson-nav-btns {
  display: flex;
  gap: 12px;
  padding: 24px 20px;
  border-top: 1px solid var\(--border\);
  margin-top: auto;
}

.lesson-btn {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 20px;
  border: 1px solid var\(--border\);
  border-radius: 12px;
  background: white;
  color: var\(--text-dark\);
  font-size: 15px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
}

.lesson-btn:hover:not\(.disabled\) {
  background: var\(--bg-blue\);
  border-color: var\(--blue\);
  transform: translateY\(-1px\);
}

.lesson-btn.primary {
  background: var\(--blue\);
  color: white;
  border-color: var\(--blue\);
}

.lesson-btn.primary:hover {
  background: #2563eb;
  box-shadow: 0 4px 12px rgba\(59, 130, 246, 0.3\);
}

.lesson-btn.disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.lesson-btn i {
  width: 18px;
  height: 18px;
}

/* Quiz Container */
.quiz-container {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.quiz-question {
  text-align: center;
  padding: 24px;
  background: var\(--bg-blue\);
  border-radius: 16px;
  position: relative;
}

.quiz-prompt {
  font-size: 16px;
  color: var\(--text-med\);
  margin-bottom: 20px;
  font-weight: 500;
}

.quiz-word {
  margin-bottom: 8px;
}

.quiz-hanzi {
  font-family: "Noto Serif SC", serif;
  font-size: 56px;
  font-weight: 400;
  color: var\(--text-dark\);
  margin-bottom: 12px;
}

.quiz-pinyin {
  font-size: 20px;
  color: var\(--text-med\);
}

.quiz-audio-btn {
  position: absolute;
  top: 16px;
  right: 16px;
  width: 40px;
  height: 40px;
  border: none;
  border-radius: 50%;
  background: white;
  color: var\(--blue\);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  box-shadow: 0 2px 8px rgba\(0,0,0,0.1\);
  transition: all 0.2s ease;
}

.quiz-audio-btn:hover {
  background: var\(--blue\);
  color: white;
  transform: scale\(1.1\);
}

.quiz-audio-btn i {
  width: 20px;
  height: 20px;
}

.quiz-choices {
  display: grid;
  gap: 12px;
}

.quiz-choice {
  padding: 16px 20px;
  border: 2px solid var\(--border\);
  border-radius: 12px;
  background: white;
  color: var\(--text-dark\);
  font-size: 16px;
  font-weight: 500;
  cursor: pointer;
  text-align: left;
  transition: all 0.2s ease;
}

.quiz-choice:hover:not\(:disabled\) {
  background: var\(--bg-blue\);
  border-color: var\(--blue\);
  transform: translateX\(4px\);
}

.quiz-choice:disabled {
  cursor: not-allowed;
}

.quiz-choice.correct {
  background: #d1fae5;
  border-color: var\(--green\);
  color: var\(--green\);
}

.quiz-choice.incorrect {
  background: #fee2e2;
  border-color: var\(--red\);
  color: var\(--red\);
}

.quiz-feedback {
  min-height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.feedback-correct,
.feedback-incorrect {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 20px;
  border-radius: 12px;
  font-size: 16px;
  font-weight: 600;
}

.feedback-correct {
  background: #d1fae5;
  color: var\(--green\);
}

.feedback-incorrect {
  background: #fee2e2;
  color: var\(--red\);
}

.feedback-correct i,
.feedback-incorrect i {
  width: 20px;
  height: 20px;
}

/* Speak Mode */
.speak-container {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.speak-instruction {
  text-align: center;
  font-size: 18px;
  color: var\(--text-med\);
  font-weight: 500;
  margin-bottom: 8px;
}

.speak-word {
  text-align: center;
  padding: 32px;
  background: var\(--bg-blue\);
  border-radius: 16px;
}

.speak-hanzi {
  font-family: "Noto Serif SC", serif;
  font-size: 64px;
  font-weight: 400;
  color: var\(--text-dark\);
  margin-bottom: 12px;
}

.speak-pinyin {
  font-size: 24px;
  color: var\(--text-med\);
  margin-bottom: 16px;
}

.speak-en {
  font-size: 18px;
  color: var\(--text-light\);
  font-weight: 500;
}

.speak-controls {
  display: flex;
  gap: 12px;
}

.speak-btn-listen,
.speak-btn-record {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 16px 20px;
  border-radius: 12px;
  font-size: 16px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}

.speak-btn-listen {
  background: var\(--blue\);
  color: white;
  border: none;
}

.speak-btn-listen:hover {
  background: #2563eb;
  transform: translateY\(-2px\);
  box-shadow: 0 6px 20px rgba\(59, 130, 246, 0.3\);
}

.speak-btn-record {
  background: white;
  color: var\(--red\);
  border: 2px solid var\(--border\);
}

.speak-btn-record:hover {
  background: var\(--red\);
  color: white;
  border-color: var\(--red\);
}

.speak-btn-record.recording {
  background: var\(--red\);
  color: white;
  border-color: var\(--red\);
  animation: pulse 1.5s infinite;
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

.speak-btn-listen i,
.speak-btn-record i {
  width: 20px;
  height: 20px;
}

.speak-tips {
  background: white;
  border: 1px solid var\(--border\);
  border-radius: 12px;
  padding: 16px 20px;
}

.speak-tip-title {
  font-size: 14px;
  font-weight: 600;
  color: var\(--text-dark\);
  margin-bottom: 12px;
}

.speak-tip {
  font-size: 13px;
  color: var\(--text-med\);
  line-height: 1.6;
  margin-bottom: 6px;
}

/* Lesson Complete Screen */
.lesson-complete {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 48px 20px;
  text-align: center;
  min-height: 500px;
}

.complete-icon {
  width: 96px;
  height: 96px;
  border-radius: 50%;
  background: linear-gradient\(135deg, var\(--orange\), var\(--red\)\);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
  animation: scaleIn 0.5s ease;
}

@keyframes scaleIn {
  0% { transform: scale\(0\); }
  50% { transform: scale\(1.1\); }
  100% { transform: scale\(1\); }
}

.complete-icon i {
  width: 56px;
  height: 56px;
  color: white;
  stroke-width: 2;
}

.complete-title {
  font-family: "Playfair Display", serif;
  font-size: 32px;
  font-weight: 400;
  color: var\(--text-dark\);
  margin-bottom: 32px;
}

.complete-stats {
  display: grid;
  grid-template-columns: repeat\(3, 1fr\);
  gap: 20px;
  width: 100%;
  max-width: 500px;
  margin-bottom: 40px;
}

.complete-stat {
  background: var\(--bg-blue\);
  border-radius: 16px;
  padding: 20px 12px;
}

.complete-stat-value {
  font-size: 32px;
  font-weight: 700;
  color: var\(--blue\);
  margin-bottom: 8px;
}

.complete-stat-label {
  font-size: 12px;
  color: var\(--text-med\);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.complete-actions {
  display: flex;
  gap: 12px;
  width: 100%;
  max-width: 400px;
}
EOF)

