import { AppProvider, useApp } from './contexts/AppContext';
import Flashcard from './components/Flashcard';

function LessonDemo\(\) {
  const { state, nextWord, prevWord } = useApp\(\);
  const { activeLesson, lessonWordIndex } = state;

  if \(!activeLesson\) {
    return \(
      <div className="min-h-screen bg-white flex items-center justify-center">
        <div className="text-center">
          <h1 className="text-4xl font-playfair font-bold text-text-dark mb-4">
            Sonus
          </h1>
          <p className="text-text-med mb-6">
            React + TypeScript + Vite version
          </p>
          <p className="text-sm text-text-light">
            No lesson loaded yet. Check SETUP.md for next steps!
          </p>
        </div>
      </div>
    \);
  }

  const currentWord = activeLesson.words[lessonWordIndex];

  return \(
    <div className="min-h-screen bg-white flex flex-col">
      <header className="bg-white border-b border-border p-4">
        <div className="max-w-2xl mx-auto">
          <h2 className="text-2xl font-playfair font-bold text-text-dark">
            Lesson {activeLesson.lessonIndex + 1}
          </h2>
          <p className="text-sm text-text-med">
            {activeLesson.words.length} words · Learn · Practice
          </p>
        </div>
      </header>

      <main className="flex-1 max-w-2xl w-full mx-auto">
        <Flashcard
          word={currentWord}
          currentIndex={lessonWordIndex}
          totalWords={activeLesson.words.length}
          onNext={nextWord}
          onPrev={prevWord}
        />
      </main>
    </div>
  \);
}

export default function App\(\) {
  return \(
    <AppProvider>
      <LessonDemo />
    </AppProvider>
  \);
}
